const xml = $input.item.json.data || '';

const feedTitleMatch = xml.match(/<title>(.*?)<\/title>/);
const feedTitle = feedTitleMatch ? feedTitleMatch[1] : '';

let brand = 'Unknown';
if (feedTitle.includes('Cava')) brand = 'Cava';
else if (feedTitle.includes('Sweetgreen')) brand = 'Sweetgreen';
else if (feedTitle.includes('Chipotle')) brand = 'Chipotle';
else if (feedTitle.includes('Shake Shack')) brand = 'Shake Shack';

const titleMatches = [...xml.matchAll(/<title><!\[CDATA\[(.*?)\]\]><\/title>|<title>(.*?)<\/title>/g)];
const headlines = titleMatches
  .slice(1)
  .map(m => (m[1] || m[2] || '').trim())
  .filter(t => t.length > 0)
  .slice(0, 8);

let section = '\n## ' + brand + '\n';
headlines.forEach(function(h, idx) {
  section += (idx + 1) + '. ' + h + '\n';
});

return { brand: brand, section: section };

const briefText = $input.item.json.content[0].text;
const today = new Date().toISOString().split('T')[0];

const blocks = [];

for (const rawLine of briefText.split('\n')) {
  const line = rawLine.trimEnd();

  if (!line.trim()) continue;

  if (line.startsWith('## ')) {
    blocks.push({
      object: 'block',
      type: 'heading_2',
      heading_2: {
        rich_text: [{ type: 'text', text: { content: line.slice(3).trim() } }]
      }
    });
  } else if (line.match(/^[-*] /)) {
    blocks.push({
      object: 'block',
      type: 'bulleted_list_item',
      bulleted_list_item: {
        rich_text: [{ type: 'text', text: { content: line.slice(2).trim() } }]
      }
    });
  } else {
    blocks.push({
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [{ type: 'text', text: { content: line.trim() } }]
      }
    });
  }
}

const title = 'Signal Brief — ' + today;

const body = JSON.stringify({
  parent: { database_id: 'e3d8add97b0d4fbd8879468ab3e92b15' },
  properties: {
    title: {
      title: [{ type: 'text', text: { content: title } }]
    }
  },
  children: blocks
});

return [{ json: { body: body, title: title } }];

const seenData = $getWorkflowStaticData('global');
if (!seenData.seenHeadlines) {
  seenData.seenHeadlines = [];
}

const seenSet = new Set(seenData.seenHeadlines);
const freshItems = [];
const headlineRegex = /^\d+\.\s+(.+)$/;

for (const item of items) {
  const { brand, section } = item.json;

  const freshHeadlines = [];
  for (const line of section.split('\n')) {
    const match = line.match(headlineRegex);
    if (match) {
      const headline = match[1].trim();
      if (!seenSet.has(headline)) {
        freshHeadlines.push(headline);
        seenSet.add(headline);
      }
    }
  }

  if (freshHeadlines.length === 0) continue;

  let newSection = `\n## ${brand}\n`;
  freshHeadlines.forEach((h, idx) => {
    newSection += `${idx + 1}. ${h}\n`;
  });

  freshItems.push({ json: { brand, section: newSection } });
}

// Persist back to static data
seenData.seenHeadlines = [...seenSet];

return freshItems;
